def transform(grid):
    h, w = len(grid), len(grid[0])
    bg = Counter(v for row in grid for v in row).most_common(1)[0][0]

    def segments(line):
        result = []
        i = 0
        while i < len(line):
            if line[i] == bg:
                i += 1
                continue
            color, start = line[i], i
            while i + 1 < len(line) and line[i + 1] == color:
                i += 1
            result.append((color, start, i))
            i += 1
        return result

    # Find the matching colored segments on opposing borders.
    pair = None
    for orientation, edge_a, edge_b in (
        ('horizontal', grid[0], grid[-1]),
        ('vertical', [grid[r][0] for r in range(h)], [grid[r][-1] for r in range(h)]),
    ):
        for ca, a0, a1 in segments(edge_a):
            for cb, b0, b1 in segments(edge_b):
                if ca == cb and a1 - a0 == b1 - b0:
                    pair = (orientation, ca, (a0, a1), (b0, b1))
                    break
            if pair:
                break
        if pair:
            break
    if pair is None:
        return [row[:] for row in grid]

    orientation, border_color, seg_a, seg_b = pair
    out = [row[:] for row in grid]
    markers = [(r, c, grid[r][c]) for r in range(h) for c in range(w)
               if grid[r][c] != bg and grid[r][c] != border_color]

    for r, c, color in markers:
        axis = c if orientation == 'horizontal' else r
        if seg_a[0] <= axis <= seg_a[1]:
            target = seg_b[0] + axis - seg_a[0]
            toward_a = True
        elif seg_b[0] <= axis <= seg_b[1]:
            target = seg_a[0] + axis - seg_b[0]
            toward_a = False
        else:
            continue

        if orientation == 'horizontal':
            # Draw from the marker toward its own border, and project across at the mapped coordinate.
            ray = range(r - 1, 0, -1) if toward_a else range(r + 1, h - 1)
            for rr in ray:
                if out[rr][c] == bg:
                    out[rr][c] = color
            for rr in range(h):
                if out[rr][target] == bg:
                    out[rr][target] = color
        else:
            ray = range(c - 1, 0, -1) if toward_a else range(c + 1, w - 1)
            for cc in ray:
                if out[r][cc] == bg:
                    out[r][cc] = color
            for cc in range(w):
                if out[target][cc] == bg:
                    out[target][cc] = color

    # Convert the original markers after drawing, preserving them as distinct endpoints.
    for r, c, _ in markers:
        out[r][c] = 4
    return out
